CREATE OR REPLACE FUNCTION calculate_disf(
    air_temperature NUMERIC,
    atmospheric_transparency NUMERIC,
    relative_humidity NUMERIC,
    lunar_distance NUMERIC
) RETURNS NUMERIC AS $$
DECLARE
    sensitivity_factor NUMERIC;
BEGIN
    sensitivity_factor := (10 - ABS(air_temperature - 15)/10) * atmospheric_transparency * (1 - relative_humidity/200) * ((100 - lunar_distance)/100);
    RETURN sensitivity_factor;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_disf(
    air_temperature NUMERIC,
    atmospheric_transparency NUMERIC,
    relative_humidity NUMERIC,
    lunar_distance NUMERIC
) RETURNS NUMERIC AS $$
DECLARE
    sensitivity_factor NUMERIC;
BEGIN
    sensitivity_factor := (10 - ABS(air_temperature - 15)/10) * atmospheric_transparency * (1 - relative_humidity/200) * ((100 - lunar_distance)/100);
    RETURN sensitivity_factor;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_disf(
    air_temperature NUMERIC,
    atmospheric_transparency NUMERIC,
    relative_humidity NUMERIC,
    lunar_distance NUMERIC,
    min_threshold NUMERIC DEFAULT 0
) RETURNS NUMERIC AS $$
DECLARE
    sensitivity_factor NUMERIC;
BEGIN
    sensitivity_factor := (10 - ABS(air_temperature - 15)/10) * atmospheric_transparency * (1 - relative_humidity/200) * ((100 - lunar_distance)/100);
    IF sensitivity_factor < min_threshold THEN
        sensitivity_factor := min_threshold;
    END IF;
    RETURN sensitivity_factor;
END;
$$ LANGUAGE plpgsql;
